"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[1828],{55909:e=>{e.exports=JSON.parse('{"functions":[],"properties":[],"types":[],"name":"Monetization","desc":"Thin wrapper around `Monetization.Generated.luau` (auto-regenerated on\\nevery `rblxsync run`). Adds by-name lookups so consumers can reference\\nproducts / passes / badges by their human-readable name without\\npasting fresh IDs every time rblxsync reissues one.\\n\\nRe-exports the raw `Universe` / `GamePasses` / `DeveloperProducts` /\\n`Badges` tables from Generated so callers can iterate directly when\\nthey need to.\\n\\nLookup misses warn loudly and return 0 \u2014 a typo or a name that hasn\'t\\nbeen synced yet should fail visibly in the console rather than\\nsilently breaking a purchase flow.","source":{"line":20,"path":"src/Shared/Data/Monetization/init.luau"}}')}}]);